A.Ow=new B.y(A.an,"Cara memisahkan campuran",A.K,"Ayo cari tahu cara memisahkan campuran!",null,"Tulis contoh tiap cara di papan.",A.aFq,!0,null,null)
A.Ly=new B.y(A.ao,"Saring & jemur!",A.K,"Sekarang kita jadi ilmuwan pemisah campuran!","Saring air kotor lewat kain \u2014 amati air jadi jernih dan kotoran tertahan. Jemur sedikit air garam di piring sampai airnya menguap, lihat kristal garam muncul. (Air ini bukan untuk diminum.)",null,null,!1,null,null)
A.aMj=new B.aD("Garam yang sudah larut hilang selamanya.","Garam tidak hilang, hanya larut. Saat airnya menguap, garam tertinggal kembali. Jemur sedikit air garam untuk membuktikannya.")
A.aMp=new B.aD("Semua campuran dipisahkan dengan cara yang sama.","Caranya berbeda: pasir + air disaring, air garam diuapkan, serbuk besi diambil magnet. Sesuaikan cara dengan sifat bahannya.")
A.aDk=s([A.aMj,A.aMp],t.v)
A.LB=new B.y(A.ar,"Cek pemahaman",A.U,"Si Jabrik bingung \u2014 bantu dia! Cara apa yang dipakai untuk mengambil garam kembali dari air garam? Dan cara apa untuk memisahkan pasir dari air?",u.r,null,null,!0,null,A.aDk)
A.LG=new B.y(A.as,"WHAT?! \ud83e\udd2f",A.au,"Tahukah kalian? Garam dapur yang kita pakai setiap hari sebagian besar dibuat dengan cara MENGUAPKAN air laut. Air laut dialirkan ke petak-petak tambak, dijemur matahari sampai airnya menguap, dan garam putihnya tertinggal \u2014 persis seperti percobaan kita tadi!","Tepuk tangan untuk petani garam dan sains pemisahan!",null,null,!1,"Teknologi modern memisahkan sampah untuk didaur ulang dan menyaring air kotor menjadi bersih \u2014 semuanya memakai ilmu memisahkan campuran.",null)
A.aFt=s([A.MQ,A.Mb,A.Ow,A.Ly,A.LB,A.LG],t.u)
